/**
 * Type declaration for assetState.js when imported as text via wrangler rules
 *
 * Wrangler is configured to import this file as raw text (type = "Text"),
 * so it's exposed as a string containing the JavaScript source code.
 *
 * @see wrangler.toml rules configuration
 * @see Story E1 - Asset State Model
 */
declare const assetStateModule: string;
export default assetStateModule;
